import React, { useState } from 'react';
import axios from 'axios';

function Register({ onRegister }) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    try {
      await axios.post('http://localhost:5000/api/auth/register', {
        name, email, password, role
      });
      setSuccess('Registration successful! You can now log in.');
      setName(''); setEmail(''); setPassword(''); setRole('student');
      if (onRegister) onRegister();
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed');
    }
  };

  return (
    <div className="max-w-md mx-auto mt-15 p-8 bg-white rounded-xl shadow-xl flex flex-col items-center">
      <form onSubmit={handleSubmit} className="w-full">
        <div className="text-2xl font-bold mb-6 text-gray-800 text-center">Register</div>
        {error && <div className="text-red-600 mb-3 text-center text-sm">{error}</div>}
        {success && <div className="text-green-600 mb-3 text-center text-sm">{success}</div>}
        <input
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="text"
          placeholder="Name"
          value={name}
          onChange={e => setName(e.target.value)}
          required
        />
        <input
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="email"
          placeholder="Email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          required
        />
        <input
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="password"
          placeholder="Password"
          value={password}
          onChange={e => setPassword(e.target.value)}
          required
        />
        <select
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-gray-50 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          value={role}
          onChange={e => setRole(e.target.value)}
        >
          <option value="student">Student</option>
          <option value="librarian">Librarian</option>
        </select>
        <button 
          className="w-full p-3 bg-gradient-button text-white font-semibold border-none rounded-lg cursor-pointer text-base hover:bg-gradient-button-hover transition-all duration-200"
          type="submit"
        >
          Register
        </button>
      </form>
    </div>
  );
}

export default Register;
